buscar ƒ:
() => {
    // Paleta de búsqueda (Ctrl+K): filtra por nombre y, si no acierta, por el
    // TEXTO del átomo (código ƒ, §, <, {). Enter o clic teletransporta. El
    // overlay, el teclado y los resultados los dibuja el shell (host.palette);
    // aquí queda solo la LÓGICA: filtrar y a dónde ir. Ver CONTENEDOR.md.
    const filtrar = (q) => {
        q = q.trim().toLowerCase();
        if (!q) return [];
        const res = [];
        for (const k of diarsaba.keys()) {
            if (typeof k !== "string" || k.endsWith("֎")) continue;
            const nombre = k.toLowerCase();
            let score = -1;
            const idx = nombre.indexOf(q);
            // El nombre pesa más que el contenido, y cuanto antes aparezca.
            if (idx >= 0) score = 1000 - idx;
            else {
                const v = diarsaba.get(k);
                let texto = "";
                if (typeof v === "function") texto = String(v).toLowerCase();
                else if (typeof v === "string") texto = v.toLowerCase();
                if (texto && texto.includes(q)) score = 10;
            }
            if (score >= 0) res.push({ k, score });
        }
        res.sort((a, b) => b.score - a.score || a.k.localeCompare(b.k));
        return res.slice(0, 25).map((r) => r.k);
    };

    host.palette({ onQuery: filtrar, onPick: (k) => diarsaba.get("ir a ƒ")(k) });
}

