despachar menú ƒ:
async (p) => {
    // Despacha el clic sobre un ítem de MENÚ o LISTA. Antes vivía dentro de
    // "handle click ƒ" leyendo el DOM (textContent, dataset, getBoundingClientRect);
    // ahora recibe DATOS semánticos del shell (host.menu/host.list vía onPick):
    //   p = { label, index, rect, parent, current }
    // Así el despacho no toca el DOM — es el paso que lo deja listo para el
    // worker. "rect" es la caja del ítem, para anclar submenús y sublistas.
    const content = p.label;
    const rect = p.rect;
    const dataset = { parent: p.parent, current: p.current };
    const clear = () => diarsaba.get("clear menus ƒ")();

    // "@ place": crea un place nuevo (no nombra un átomo, pide crearlo).
    if (content === "@ place") { diarsaba.get("new place ƒ")(); clear(); return; }

    // Ítem SIN prefijo "[n] " (de MENÚ): manda el sigilo de la derecha.
    if (!/^\[\d+\]/.test(content)) {
        const tipo = content.slice(-1);
        if (diarsaba.get("types list #").includes(tipo)) {
            if (tipo === "#") {
                // Una lista dentro de un menú se abre como SUBmenú (sigue siendo
                // menú). El padre se queda abierto.
                if (diarsaba.get("open submenu ƒ")(content, rect)) return;
            } else {
                if (diarsaba.get("dispatch item ƒ")(content, dataset, rect)) { clear(); return; }
            }
        }
        // Creador de chip ("ƒ func" → create ƒ func ƒ): pide nombre y crea.
        const createFn = diarsaba.get(`create ${content} ƒ`);
        if (typeof createFn === "function") {
            host.clearMenus();
            const name = await diarsaba.get("modal input ƒ")(content.slice(0, 1));
            if (name != null && name !== "") {
                diarsaba.get("add to place ƒ")(name);
                createFn(name);
                await diarsaba.get("persistir atomo ƒ")(name);
                const chip = diarsaba.get("create chip ƒ")(
                    diarsaba.get("open x $"),
                    diarsaba.get("open y $"),
                    name, "", content.slice(0, 1)
                );
                host.scene.register(name, chip);
            }
            clear();
            return;
        }
        // Opción de chip ("· * quitar", "· ƒ editor"…): corre "<label> ƒ".
        const fn = diarsaba.get(`${content} ƒ`);
        if (fn) fn(dataset);
        clear();
        return;
    }

    // Ítem de LISTA "[n] texto": se parsea el índice y se despacha limpio.
    try {
        const parsed = diarsaba.get("obtener index [0] ƒ")(content);
        const label = parsed.texto;
        const handled = diarsaba.get("dispatch item ƒ")(label, dataset, rect);
        if (!handled) {
            const fn = diarsaba.get(`${label} ƒ`) || diarsaba.get(`${content} ƒ`);
            if (fn) fn(dataset);
        }
    } catch (err) { /* parseo inválido: se ignora */ }
    clear();
}

dispatch item ƒ:
(name, dataset, rect) => {
    // Un ítem de lista "cobra vida" según su sigilo. Devuelve true si lo manejó.
    // Recibe "rect" (la caja del ítem, dato del shell) en vez del elemento DOM:
    // así ancla la sublista sin tocar el DOM. Ver despachar menú ƒ.
    const type = name.slice(-1);

    // Acciones y threads: ejecutar
    if (type === "!" || type === "~") {
        threads(name);
        return true;
    }

    // Listas: abrir su contenido como sublista efímera junto al ítem
    if (type === "#") {
        const list = diarsaba.get(name);
        if (!Array.isArray(list)) return false;
        const sub = diarsaba.get("create list ƒ")(rect.right + 6, rect.top, list, name);
        host.scene.openList(name, sub);
        return true;
    }

    // Places: abrirlos (el ítem ya viene con el nombre limpio, sin "[n] ").
    if (type === "@") {
        const abrir = diarsaba.get("on double tap place ƒ");
        if (typeof abrir !== "function") return false;
        diarsaba.set("pointer up event", { name: name });
        diarsaba.get("clear menus ƒ")();
        abrir();
        return true;
    }

    // Funciones: ejecutar
    if (type === "ƒ") {
        const f = diarsaba.get(name);
        if (typeof f === "function") {
            f(dataset);
            return true;
        }
        return false;
    }

    return false;
}

