guardar ! ƒ:
async () => {
    // No persistir refs DOM (claves terminadas en ֎) ni objetos vivos de
    // runtime: se regeneran solos y solo ensucian el archivo (y provocan
    // entradas {} que rompen código que espera un elemento).
    const skipKeys = new Set([
        "ws socket",
        "salida #",
        "Streams info #",
        "Streams data #",
        "current menu",
        "current chip menu",
        "pointer up event",
        "pointer down event",
        "pointer move event"
    ]);

    const dataToSave = {};
    for (const [key, value] of diarsaba.entries()) {
        if (key.endsWith("֎") || skipKeys.has(key)) continue;

        if (key.endsWith("ƒ")) {
            dataToSave[key] = String(value).replace(/\r\n/g, "\n").trim();
        } else {
            dataToSave[key] = value;
        }
    }
    const jsonString = JSON.stringify(dataToSave, null, 2);

    try {
        const savedPath = await host.save(jsonString);
        console.log("Archivo guardado exitosamente en:", savedPath);
    } catch (error) {
        console.error("Error al guardar el archivo:", error);
    }
}

handle click ƒ:
async () => {
    // Con el modo mover activo, un clic en un CHIP lo arrastra y no lo abre.
    if (diarsaba.get("moviendo chips §")) {
        const ev = diarsaba.get("pointer up event");
        if (ev && ev.kind === "chip") return;
    }

    // En panorámica un clic sobre un chip vuela a su place; en el vacío sale;
    // un ARRASTRE (pan de la cámara) no hace ninguna de las dos.
    if (diarsaba.get("panorámica activa §")) {
        const up = diarsaba.get("pointer up event");
        const down = diarsaba.get("pointer down event");
        const arrastro = down && up
            && Math.hypot(up.clientX - down.clientX, up.clientY - down.clientY) > 6;
        if (up.kind === "chip" && up.pano) diarsaba.get("panorámica entrar ƒ")(up.pano);
        else if (!arrastro) diarsaba.get("panorámica ƒ")();
        return;
    }

    // El clic llega ya CLASIFICADO por el shell (host.hit → pointer up event):
    // kind = modal | menu | background | chip. El átomo no toca event.target.
    const event = diarsaba.get("pointer up event");

    // Modales (editor Monaco, modal de nombre) y menús/listas (se despachan
    // solos vía host.menu/host.list) no siguen aquí.
    if (event.kind === "modal" || event.kind === "menu") return;

    // Fondo (body o escena 3d vacía) → solo limpiar menús.
    if (event.kind === "background") {
        diarsaba.get("clear menus ƒ")();
        return;
    }

    // Chip del lienzo: el doble clic abre su editor (o cambia de place si es @).
    const content = event.name;
    let last_click = diarsaba.get("last click on §");
    if (last_click == undefined || last_click == null) {
        diarsaba.set("last click on §", content);
    } else {
        if (last_click == content) {
            if (content.slice(-1) == "@") {
                diarsaba.get("on double tap place ƒ")();
            } else {
                const editables = diarsaba.get("editables list #");
                if (editables.includes(content.slice(-1))) {
                    diarsaba.get("open general editor ƒ")(content);
                }
            }
            diarsaba.set("last click on §", null);
        } else {
            diarsaba.set("last click on §", content);
        }
    }

    diarsaba.get("clear menus ƒ")();
}

