new place ƒ:
async () => {
    //preguntamos el nombre
    //creamos un chip
    // al dar click en el chip el toma control del contexto del bodi
    // todo lo creado o eliminado se agencia al chip
    // si se da click en otro place para ser avierto ahora ese chip pasa a tener la agencia

    const name = await diarsaba.get("modal input ƒ")("@");

    if (name == "" || name == null)
        return


    const place_exist = diarsaba.get(name)
    //si no existe creamos su place
    if (place_exist == null || place_exist == undefined) {
        diarsaba.set(name, {})
        // Autosave: el place nuevo (vacío) ya es un átomo persistible.
        await diarsaba.get("persistir atomo ƒ")(name);
    } else {
        //si ya existe no hacemos nada
    }


    //tenemos ahora el chip con el que interactuar
    const chip = diarsaba.get("create chip ƒ")(
        diarsaba.get("open x $"),
        diarsaba.get("open y $"),
        name,
        "",
        "@");


    const current_place_name = diarsaba.get("current place §")

    if (current_place_name == null || current_place_name == undefined) {
        //si no existe un place ahora somos el place
        diarsaba.set("current place §", name)
    } else {
        // 1. Declaramos la variable y evitamos que sea undefined
        let current_place = diarsaba.get(current_place_name) || {};

        // 2. Usamos un nombre de variable más seguro (asumiendo que 'name' viene de otro lado)
        const itemKey = name;

        // 3. Creamos un nuevo objeto (inmutabilidad) usando el spread operator (...)
        const updated_place = {
            ...current_place,
            [itemKey]: {
                x: diarsaba.get("open x $"),
                y: diarsaba.get("open y $")
            }
        };

        // 4. Guardamos el nuevo objeto
        diarsaba.set(current_place_name, updated_place);
        // Autosave: el place actual ahora contiene el place nuevo.
        await diarsaba.get("persistir atomo ƒ")(current_place_name);
    }

}

obtener index [0] ƒ:
(texto) => {
    const regex = /^\[(\d+)\]\s*(.*)$/;
    const match = texto.match(regex);

    if (!match) {
        throw new Error('Formato inválido. Se esperaba: "[número] texto"');
    }

    return {
        indice: parseInt(match[1], 10),
        texto: match[2].trim(),
    };
}

on double tap place ƒ:
() => {

    const event = diarsaba.get("pointer up event");
    const content = event.name;

    if (content == "diarsaba-map @") {

        // 1. Calculamos los límites de la ventana UNA VEZ fuera del bucle (mejor rendimiento)
        // Añadimos un "margen" para que los chips no queden cortados en los bordes de la pantalla
        const margen = 50;
        const maximoX = window.innerWidth - margen;
        const maximoY = window.innerHeight - margen;

        diarsaba.forEach((valor, clave) => {
            // 2. Generamos las coordenadas aleatorias
            // Math.random() da un decimal entre 0 y 1. Lo multiplicamos por el máximo.
            // Usamos Math.floor() para redondear a números enteros (los píxeles suelen ser enteros)
            // Sumamos el margen para que empiece desde el margen y no desde el 0 absoluto.
            const xAleatorio = Math.floor(Math.random() * maximoX) + margen;
            const yAleatorio = Math.floor(Math.random() * maximoY) + margen;

            // 3. Llamamos a la función con los nuevos valores
            const chip = diarsaba.get("create chip ƒ")(
                xAleatorio,
                yAleatorio,
                clave,
                "",
                clave.slice(-1)
            );
        });

        //en caso opuesto a esto, mejor crear una lista y que habra automaticamente en el editor
    } else {
        // El registro de chips vive en host.scene; al limpiar la escena para
        // el nuevo place se vacía solo (clear → forgetChips). La infraestructura
        // del lienzo (escena 3d, canvas del grafo) sobrevive: no está en él.
        diarsaba.get("3d limpiar ƒ")();
        host.clearMenus(true);
        // El place nuevo se pintó para el encuadre inicial: la cámara vuelve.
        diarsaba.get("3d reset ƒ")();

        const chip = diarsaba.get("create chip ƒ")(
            100,
            50,
            content,
            "",
            content.slice(-1)
        );
        host.scene.register(content, chip);

        // Desestructuramos el array en [clave, valor]
        let place = diarsaba.get(content)
        Object.entries(place).forEach(([clave, valor]) => {
            const chip = diarsaba.get("create chip ƒ")(
                valor.x,
                valor.y,
                clave,
                "",
                clave.slice(-1)
            );

            // Sin esta referencia, abrir/ocultar/padre no encuentran el
            // chip y anclan al puntero: el hijo sale desplazado.
            host.scene.register(clave, chip);
        });


        diarsaba.set("current place §", content)

        // Con el modo grafo activo, las aristas son de OTRO place: recalcular.
        if (diarsaba.get("grafo activo §")) {
            diarsaba.get("grafo activar ƒ")();
            diarsaba.get("3d render ƒ")();
