p2p ƒ @ StreamHandle ƒ:
async () => {
    // Deja la app lista para RECIBIR. La llama "on start ƒ", así que no hace
    // falta tocarla: al abrir la app ya se escucha.
    //
    // Modelo persistente: cada peer abre UN stream y por él manda muchos
    // mensajes enmarcados por "\n". Aquí se registra ese stream en "conns ֎" y
    // se arranca su lector continuo; cada mensaje completo va a "recibir ƒ".
    // Con N peers hay N streams, cada uno con su lector y su buffer, en paralelo.
    const dice = diarsaba.get("p2p ƒ @ dice ƒ");
    try {
        // Idempotente: suscribirse dos veces duplicaría cada entrada.
        if (diarsaba.get("p2p ƒ @ escuchando ֎")) return "ya escuchaba";

        diarsaba.set(
            "p2p ƒ @ escuchando ֎",
            host.events("p2p:stream", (ev) => {
                try {
                    let conns = diarsaba.get("p2p ƒ @ conns ֎");
                    if (!conns) { conns = new Map(); diarsaba.set("p2p ƒ @ conns ֎", conns); }
                    const s = diarsaba.get("p2p ƒ @ stream ƒ")(ev.stream, ev.from);
                    // (Glare: si ya había un stream con ese peer —porque yo se lo
                    // abrí—, este entrante lo reemplaza. Poco frecuente; se
                    // resolvería con una convención de quién abre.)
                    conns.set(ev.from, s);
                    // Fire-and-forget: escuchar es un bucle que vive hasta el EOF.
                    s.escuchar((msg) => diarsaba.get("p2p ƒ @ recibir ƒ")(ev.from, msg));
                } catch (e) {
                    console.error("[p2p ƒ] no se pudo registrar el stream entrante", e);
                }
            })
        );

        await host.p2p.Start();
        return dice("StreamHandle", "escuchando: lo entrante aparece en «Streams info #» / «Streams data #»");
    } catch (e) {
        // Sin alert: esto corre al arrancar y un modal dejaría la app
        // inservible. El fallo queda en la consola y en "p2p ƒ @ dice §".
        diarsaba.set("p2p ƒ @ dice §", `StreamHandle ✗\n${e.message || e}`);
        console.error("[p2p ƒ] no se pudo escuchar:", e);
        return e;
    }
}

p2p ƒ @ abrir o reusar ƒ:
async (peer) => {
    // Devuelve el stream persistente hacia ese peer, abriéndolo solo si no
    // había. El stream es bidireccional: lo que YO abro también lo escucho, así
    // que por el mismo canal puedo recibir sus mensajes.
    let conns = diarsaba.get("p2p ƒ @ conns ֎");
    if (!conns) { conns = new Map(); diarsaba.set("p2p ƒ @ conns ֎", conns); }
    if (conns.has(peer)) return conns.get(peer);

    const id = await host.p2p.OpenStream(peer, 30000);
    const s = diarsaba.get("p2p ƒ @ stream ƒ")(id, peer);
    conns.set(peer, s);
    s.escuchar((msg) => diarsaba.get("p2p ƒ @ recibir ƒ")(peer, msg));
    return s;
}

p2p ƒ @ arg ƒ:
(v) => {
    // Un ejecutor ! pasa los elementos del arreglo COMO STRINGS: threads hace
    // a.apply(null, s.slice(1)), así que llega el NOMBRE del átomo, no su
    // valor. Por eso cada ƒ resuelve aquí: si el string nombra un átomo, se
    // usa su contenido; si no, se toma tal cual como literal.
    //
    // Es lo que permite ["... Announce ƒ", "valor para anunciar §"] sin que la
    // ƒ tenga que saber de dónde viene el dato.
    if (typeof v !== "string") return v;
    return diarsaba.has(v) ? diarsaba.get(v) : v;
}

