p2p ƒ @ difundir ƒ:
async (valor) => {
    // Manda a TODOS los peers conectados por sus streams persistentes. arg ƒ
    // resuelve el nombre del átomo (un ! pasa "p2p ƒ @ enviar :" como string).
    const dice = diarsaba.get("p2p ƒ @ dice ƒ");
    const arg = diarsaba.get("p2p ƒ @ arg ƒ");
    const conns = diarsaba.get("p2p ƒ @ conns ֎");
    if (!conns || conns.size === 0) return dice("difundir", "no hay peers conectados");
    const carga = valor === undefined ? diarsaba.get("p2p ƒ @ enviar :") : arg(valor);
    let ok = 0;
    for (const s of conns.values()) {
        try { await s.escribir(carga === undefined ? null : carga); ok++; } catch (_) {}
    }
    return dice("difundir", { a: `${ok} peers`, envié: carga });
}

