ver version ƒ:
async (name, version) => {
    // Abre un diff Monaco: a la izquierda la versión elegida, a la derecha lo
    // actual. Si se pulsa "restaurar", aplica esa versión. El lenguaje se elige
    // por el sigilo, igual que el editor general.
    const sig = name.slice(-1);
    const lang = sig === "ƒ" ? "js"
        : (sig === "@" || sig === ":" || sig === "#") ? "json"
        : sig === "<" ? "html"
        : sig === "{" ? "css"
        : "text";

    const serial = (v) => {
        if (sig === "ƒ") return typeof v === "function" ? v.toString() : String(v);
        if (typeof v === "string") return v;
        try { return JSON.stringify(v, null, 2); } catch (_) { return String(v); }
    };

    // version.value ya viene en su forma natural (código fuente para ƒ, objeto
    // para @/:, etc.); actual es el valor vivo del mapa.
    const versionStr = serial(version.value);
    const actualStr = serial(diarsaba.get(name));

    const restaurar = await host.diff(
        `${name}  ·  #${version.seq}`,
        versionStr,
        actualStr,
        lang
    );

    if (restaurar) await diarsaba.get("restaurar version ƒ")(name, version);
}

