· * eliminar ƒ:
async (dataset) => {
    // Borrado DEFINITIVO: elimina el átomo de diarsaba, sus chips del DOM y
    // todas las referencias en cualquier place.
    const name = dataset.parent;

    // 1. Quitar chips del DOM (principal y posibles hijos abiertos) y sus refs
    host.scene.removeAll(name);

    // 2. Quitar la referencia de TODOS los places que lo contengan
    const placesTocados = [];
    for (const [k, v] of diarsaba.entries()) {
        if (typeof k === "string" && k.endsWith("@") && v && typeof v === "object") {
            if (Object.prototype.hasOwnProperty.call(v, name)) {
                const { [name]: _omit, ...rest } = v;
                diarsaba.set(k, rest);
                placesTocados.push(k);
            }
        }
    }

    // 3. Borrar el átomo de diarsaba (definitivo)
    diarsaba.delete(name);

    // 4. Propagar a la base: sin esto el átomo RESUCITA al recargar
    //    (LoadPredefinedFunctions rehace el mapa desde bbolt) y los places
    //    quedarían apuntando a un fantasma. DeleteAtom versiona el valor,
    //    así que el borrado sigue siendo recuperable.
    const persist = diarsaba.get("persistir atomo ƒ");
    for (const k of placesTocados) await persist(k);
    if (typeof window.DeleteAtom === "function") {
        try { await host.kv.del(name); }
        catch (e) { console.error(`no se pudo borrar "${name}" de la base:`, e); }
    }
}

· * historial ƒ:
async (dataset) => {
    // Historial navegable: lista las versiones anteriores del átomo (bbolt las
    // guarda en cada autosave) como panel junto a su chip. Elegir una abre un
    // diff (ver version ƒ). El panel clicable lo dibuja el shell (host.picker);
    // aquí queda la LÓGICA: traer las versiones y formatearlas. Ver CONTENEDOR.md.
    const name = dataset && dataset.parent;
    if (!name) return;

    if (!host.tieneBackend) {
        host.notify("El historial vive en la base (bbolt): ábrelo desde la app, no desde el frontend suelto.");
        return;
    }

    let versiones;
    try {
        versiones = JSON.parse(await host.kv.history(name));
    } catch (e) {
        host.notify(`no se pudo leer el historial de "${name}": ${e && e.message ? e.message : e}`);
        return;
    }
    if (!versiones.length) {
        host.notify(`"${name}" no tiene versiones anteriores.`);
        return;
    }

    const preview = (val) => {
        let s;
        if (typeof val === "string") s = val;
        else { try { s = JSON.stringify(val); } catch (_) { s = String(val); } }
        s = String(s).replace(/\s+/g, " ").trim();
        return s.length > 48 ? s.slice(0, 45) + "…" : s;
    };

    // De la más reciente a la más antigua (así las da la base).
    const etiquetas = versiones.map((ver) => `#${ver.seq} · ${preview(ver.value)}`);
    host.picker(etiquetas, {
        anchor: { chip: name },
        onPick: ({ index }) => diarsaba.get("ver version ƒ")(name, versiones[index]),
    });
}

