· * renombrar ƒ:
async (dataset) => {
    // Renombra un átomo Y reescribe todo lo que lo nombra: places que lo tienen
    // de hijo, listas/acciones/threads que lo listan, y el CÓDIGO ƒ, textos,
    // vistas, estilos y mapas donde aparece. La red de referencias la da
    // "referencias de ƒ". Es seguro porque cada átomo tocado se versiona (autosave
    // → historial): si algo sale mal, "· * historial" lo devuelve.
    const viejo = dataset && dataset.parent;
    if (!viejo) return;

    const nuevo = ((await diarsaba.get("modal input ƒ")(viejo)) || "").trim();
    if (!nuevo || nuevo === viejo) return;

    // El sigilo (último carácter) es el TIPO: cambiarlo al renombrar rompería a
    // quien lee el átomo. Se renombra el nombre, no el tipo.
    if (nuevo.slice(-1) !== viejo.slice(-1)) {
        host.notify(`El renombrado conserva el tipo: "${nuevo}" debe terminar en "${viejo.slice(-1)}".`);
        return;
    }
    // Un nombre con comillas/barra/salto rompería el código al sustituirlo.
    if (/["\\\n]/.test(nuevo)) {
        host.notify(`"${nuevo}" no es un nombre válido (sin comillas, barras ni saltos de línea).`);
        return;
    }
    if (diarsaba.has(nuevo)) {
        host.notify(`"${nuevo}" ya existe. Elige otro nombre.`);
        return;
    }

    const reemplazar = (s) => s.split(viejo).join(nuevo);
    const tocados = [];

    // 1. Reescribir cada referencia según su tipo.
    for (const k of diarsaba.get("referencias de ƒ")(viejo)) {
        const v = diarsaba.get(k);
        if (k.endsWith("@") && v && typeof v === "object" && !Array.isArray(v)) {
            // Place: el hijo es una CLAVE; se renombra conservando su {x, y}.
            const nv = {};
            for (const [ck, cvv] of Object.entries(v)) nv[ck === viejo ? nuevo : ck] = cvv;
            diarsaba.set(k, nv);
            tocados.push(k);
        } else if (Array.isArray(v)) {
            diarsaba.set(k, v.map((x) => (x === viejo ? nuevo : x)));
            tocados.push(k);
        } else if (typeof v === "function") {
            try { diarsaba.set(k, createFunction(reemplazar(String(v)))); tocados.push(k); }
            catch (e) { console.error(`no se pudo recompilar "${k}" al renombrar:`, e); }
        } else if (typeof v === "string") {
            diarsaba.set(k, reemplazar(v));
            tocados.push(k);
        } else if (v && typeof v === "object") {
            try { diarsaba.set(k, JSON.parse(reemplazar(JSON.stringify(v)))); tocados.push(k); }
            catch (e) { console.error(`no se pudo reescribir "${k}" al renombrar:`, e); }
        }
    }

    // 2. Mover el átomo mismo (y su autorreferencia si el código se nombra).
    let valor = diarsaba.get(viejo);
    if (typeof valor === "function" && String(valor).includes(viejo)) {
        try { valor = createFunction(reemplazar(String(valor))); } catch (e) {}
    }
    diarsaba.set(nuevo, valor);
    diarsaba.delete(viejo);

    // 3. Si era el place activo, seguirlo.
    if (diarsaba.get("current place §") === viejo) diarsaba.set("current place §", nuevo);

    // 4. Chip visible: renombrar (texto + tipo, reapunta la ref, tira las
    // derivadas). Ver host.scene.rename.
    host.scene.rename(viejo, nuevo);

    // 5. Persistir todo lo tocado + el átomo nuevo, y borrar el viejo de la base
    // (si no, RESUCITA al recargar y las referencias apuntan a un fantasma).
    const persist = diarsaba.get("persistir atomo ƒ");
    for (const k of tocados) await persist(k);
    await persist(nuevo);
    if (typeof window.DeleteAtom === "function") {
        try { await host.kv.del(viejo); }
        catch (e) { console.error(`no se pudo borrar "${viejo}" de la base:`, e); }
    }

    diarsaba.get("3d render ƒ") && diarsaba.get("3d render ƒ")();
}

· * restaurar ƒ:
async (dataset) => {
    // Deshace el autosave de un átomo: lo devuelve a su versión anterior. Por
    // defecto restaura la MÁS reciente del historial (el "deshacer lo último");
    // para elegir otra o inspeccionarlas, desde consola:
    //   await window.AtomHistory("nombre del átomo")   → lista [{seq,value}]
    //   await window.RestoreAtomVersion("nombre", seq)
    // Ojo: la recuperación de un handler roto que dejó la UI inservible se hace
    // por consola, no por aquí — si el clic no responde, este átomo tampoco.
    const name = dataset && dataset.parent;
    if (!name || typeof window.AtomHistory !== "function") return;

    let versiones;
    try {
        versiones = JSON.parse(await host.kv.history(name));
    } catch (e) {
        host.notify(`no se pudo leer el historial de "${name}": ${e && e.message ? e.message : e}`);
        return;
    }
    if (!versiones.length) {
        host.notify(`"${name}" no tiene versiones anteriores.`);
        return;
    }

    try {
        await host.kv.restore(name, versiones[0].seq);
        host.notify(`"${name}" restaurado a su versión anterior.\nRecarga para verlo reflejado en el lienzo.`);
    } catch (e) {
        host.notify(`no se pudo restaurar "${name}": ${e && e.message ? e.message : e}`);
    }
}

