async (dataset) => {
    const actual = diarsaba.get(dataset.parent) || [];
    const res = await host.editor(
        dataset.parent,
        Array.isArray(actual) ? actual.join(",\n") : String(actual),
        "text"
    );

    // null = cancelado. No se toca nada: es la diferencia entre cerrar y vaciar.
    if (res == null) return;

    // "" sí vacía, pero solo si se llegó aquí GUARDANDO.
    if (res.trim() === "") {
        diarsaba.set(dataset.parent, []);
        await diarsaba.get("persistir atomo ƒ")(dataset.parent);
        return;
    }

    diarsaba.set(
        dataset.parent,
        res.split(",").map((x) => x.trim()).filter((x) => x !== "")
    );
    await diarsaba.get("persistir atomo ƒ")(dataset.parent);
}

